// Starlink Aviation — the terminal on the aircraft it flies on, converted from
// the hand-built viewer model (3d_airplane_model-main.html) rather than an OBJ
// export: the scene there is procedural, so the bake runs its own geometry code
// headlessly and merges the result.
//
// Welded on the storage grid, int16 fifths of a millimetre. Six parts, grouped by the
// viewer's materials: the terminal's white shell and its phased-array panel,
// then the airframe — body, cowling interior, fan blades, exhaust.
//
// Nothing here tilts. The aviation terminal is bolted flat to the crown of the
// fuselage and steers its beam electronically, so the hardware never moves — and
// a plane that leaned to 70° to aim would read as crashing. `baseVertex: 0` sends
// every vertex through buildDish's `plant` branch (skyGeometry.ts:462), which
// holds the model level and turns it in azimuth alone.
import type { DishModelMesh } from "./types";

export const aviationDish: DishModelMesh = {
  scale: 5,
  longAxisMm: 3000,
  parts: [
    [0, 1084, 1],
    [1084, 268, 0.94],
    [1352, 10990, 0.88],
    [12342, 576, 0.33],
    [12918, 64, 0.2],
  ],
  joint: { baseVertex: 0, pivot: [0, 0, 0] },
  beamOriginMm: [0, 210, 504],
  // A hollow body, unlike every panel: without this the camera orbits inside the
  // fuselage and the near wall clips away, leaving the interior on show.
  keepCameraOutside: true,
  positions:
    "",
  indices:
    "",
};
